<script setup>
import { ref,computed,onMounted,onBeforeUnmount } from 'vue';
import AppDialog from './AppDialog.vue';import FormField from './FormField.vue';
import { state,createPatternWithAsset,navigate } from '../state';import { windowControls } from '../storage';import { studioStorageKey } from '../example-mode.mjs';import { t,errorText } from '../i18n';
import { prepareReferenceBatch,reselectReferenceFiles,restoreReferenceReport,referenceReport,runReferenceBatch } from '../reference-import.mjs';
const emit=defineEmits(['close']),rows=ref([]),busy=ref(false),checking=ref(false),error=ref(''),closeReview=ref(false),closingApp=ref(false),stopRequested=ref(false),clearRequested=ref(false);const key=studioStorageKey('ricamo:reference-import-report');
const unfinished=computed(()=>rows.value.some(row=>!['saved','skipped'].includes(row.status)));
const counts=computed(()=>Object.fromEntries(['saved','failed','pending','skipped'].map(status=>[status,rows.value.filter(row=>row.status===status).length])));
const undecided=computed(()=>rows.value.some(row=>row.duplicate&&!row.decision&&!['saved','skipped'].includes(row.status)));
function persist(){localStorage.setItem(key,referenceReport(rows.value));}
function publish(){window.dispatchEvent(new CustomEvent('ricamo:draft-state',{detail:{pending:busy.value||checking.value||unfinished.value}}));}
function changed(){publish();}
try{rows.value=restoreReferenceReport(localStorage.getItem(key),state.value);}catch{error.value=t('reference_report_invalid');}
async function select(event){const files=Array.from(event.target.files||[]);event.target.value='';if(!files.length)return;checking.value=true;error.value='';publish();try{if(rows.value.length)await reselectReferenceFiles(rows.value,files);else rows.value=await prepareReferenceBatch(files,state.value);persist();}catch(caught){error.value=errorText(caught);}finally{checking.value=false;publish();}}
function remember(){try{persist();error.value='';}catch(caught){error.value=errorText(caught);}publish();}
async function run(mode){if(busy.value||checking.value)return;for(const row of rows.value){if(!['saved','skipped'].includes(row.status)&&!row.duplicate&&state.value.attachments.some(asset=>asset.digest===row.digest)&&!state.value.patterns.some(pattern=>pattern.id===row.id&&state.value.attachments.some(asset=>asset.id===pattern.sourceAttachmentId&&asset.digest===row.digest))){row.duplicate=true;row.decision='';}}if(undecided.value){remember();return;}busy.value=true;stopRequested.value=false;closeReview.value=false;error.value='';publish();try{await runReferenceBatch(rows.value,{mode,importOne:createPatternWithAsset,persist,changed,stopped:()=>stopRequested.value});}catch(caught){error.value=errorText(caught);}finally{busy.value=false;publish();}}
function requestClose(){stopRequested.value=true;if(busy.value||checking.value||unfinished.value)closeReview.value=true;else emit('close');}
function beforeClose(event){if(!busy.value&&!checking.value&&!unfinished.value)return;event.preventDefault();closingApp.value=true;closeReview.value=true;stopRequested.value=true;clearRequested.value=false;}
function beforeNavigate(event){if(busy.value||checking.value||unfinished.value){event.preventDefault();requestClose();}}
function beforeUnload(event){if(busy.value||checking.value||unfinished.value){event.preventDefault();event.returnValue='';}}
function stay(){clearRequested.value=false;closeReview.value=false;closingApp.value=false;windowControls?.cancelClose?.().catch(caught=>{error.value=errorText(caught);});}
async function leave(){if(busy.value||checking.value)return;if(clearRequested.value){clear();return;}try{persist();if(closingApp.value)await windowControls?.finishClose?.();else emit('close');}catch(caught){error.value=errorText(caught);}}
function reset(){if(unfinished.value){clearRequested.value=true;closeReview.value=true;}else clear();}
function open(row){emit('close');navigate('pattern',row.id);}
function rowError(code){return ['invalid_file_type','invalid_image'].includes(code)?t('reference_invalid_original'):code==='file_too_large'?t('fileTooLarge'):errorText({code});}
function clear(){clearRequested.value=false;if(busy.value||checking.value)return;rows.value=[];error.value='';closeReview.value=false;closingApp.value=false;try{localStorage.removeItem(key);}catch(caught){error.value=errorText(caught);}publish();}
onMounted(()=>{publish();window.addEventListener('ricamo:before-close',beforeClose);window.addEventListener('ricamo:before-navigate',beforeNavigate);window.addEventListener('beforeunload',beforeUnload);});
onBeforeUnmount(()=>{stopRequested.value=true;window.removeEventListener('ricamo:before-close',beforeClose);window.removeEventListener('ricamo:before-navigate',beforeNavigate);window.removeEventListener('beforeunload',beforeUnload);window.dispatchEvent(new CustomEvent('ricamo:draft-state',{detail:{pending:false}}));});
</script>
<template><AppDialog :title="t('referenceBatchTitle')" wide :busy="busy||checking" @close="requestClose"><p class="notice">{{ t('referenceBatchHelp') }}</p><p v-if="error" class="notice error" role="alert">{{ error }}</p><FormField :label="t(rows.length?'referenceReselect':'referenceChoose')" :help="t('referenceBatchLimits')" wide v-slot="{id,describedby}"><input :id="id" type="file" accept="application/pdf,image/png,image/jpeg,image/webp,image/gif" multiple :disabled="busy||checking" :aria-describedby="describedby" @change="select"/></FormField><p v-if="checking" role="status">{{ t('referenceChecking') }}</p><p v-if="rows.length" class="notice" role="status">{{ t('referenceBatchSummary',counts) }}</p><div v-if="rows.length" class="table-wrap"><table><thead><tr><th>{{ t('referenceOriginal') }}</th><th>{{ t('name') }}</th><th>{{ t('status') }}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ row.filename }}<span class="cell-subtitle">{{ Math.ceil(row.size/1024) }} KiB</span><span v-if="row.duplicate" class="badge warning">{{ t('referenceDuplicate') }}</span></td><td><input v-model="row.name" maxlength="300" :aria-label="`${t('name')}: ${row.filename}`" :disabled="busy||checking||row.attempted||row.status==='saved'" @change="remember"/><select v-if="row.duplicate&&!['saved','skipped'].includes(row.status)" v-model="row.decision" :aria-label="`${t('referenceDuplicateDecision')}: ${row.filename}`" :disabled="busy||checking" @change="remember"><option value="" disabled>{{ t('referenceChooseDecision') }}</option><option value="skip">{{ t('referenceSkipDuplicate') }}</option><option value="create">{{ t('referenceCreateDuplicate') }}</option></select></td><td><span class="badge" :class="{green:row.status==='saved',warning:row.status==='failed'}">{{ t(`referenceState_${row.status}`) }}</span><button v-if="row.status==='saved'" class="button text small" :disabled="busy||checking||unfinished" @click="open(row)">{{ t('referenceOpen') }}</button><p v-if="row.error" class="field-help">{{ rowError(row.error) }}</p><p v-if="!row.file&&!['saved','skipped'].includes(row.status)" class="field-help">{{ t('reference_reselect_needed') }}</p></td></tr></tbody></table></div><p v-if="closeReview" class="notice warning">{{ t(clearRequested?'referenceClearHelp':'referenceCloseHelp') }}</p><p v-if="stopRequested&&busy" role="status">{{ t('referenceStopping') }}</p><template #footer><template v-if="closeReview"><button class="button" :disabled="busy||checking" @click="stay">{{ t('referenceStay') }}</button><button class="button" :disabled="busy||checking" @click="leave">{{ t(clearRequested?'referenceDiscardPending':closingApp?'referenceCloseApp':'referenceCloseReport') }}</button></template><template v-else><button class="button" :disabled="checking" @click="busy?(stopRequested=true):requestClose()">{{ t(busy?'referenceStop':'close') }}</button><button v-if="rows.length&&!busy" class="button" :disabled="checking" @click="reset">{{ t('referenceNewBatch') }}</button><button v-if="counts.failed&&!busy" class="button" :disabled="checking||undecided" @click="run('failed')">{{ t('referenceRetryFailed') }}</button><button v-if="counts.pending&&!busy" class="button primary" :disabled="checking||undecided" @click="run('pending')">{{ t('referenceImportPending') }}</button></template></template></AppDialog></template>
